import {setStudyIntent,preparationLabel} from './study-intent.js?v=0.17.0';
import {studyIntentQuestions,studyIntentBadge,studyIntentPlan} from './study-intent-ui.js?v=0.17.0';
import {routeComparison} from './route-comparison.js?v=0.17.0&layout=2';
import {activityStatisticsPage,loadActivityStatistics,setActivityStatisticsSource,setActivityStatisticsPath} from './choice-statistics-ui.js?v=0.17.0';
import {createDraftSession} from './draft-session.js?v=0.17.0';
import {createActivityRecorder,recordingJourney,acquireActivityIdentity} from './activity.js?v=0.17.0';
import {freshReflection,setSubjectAnswer,orderReflectedPathways,subjectSuggestions,jordanSubjectReflection} from './subject-reflection.js?v=0.17.0';
import {subjectPage,subjectStrip,pathwayReason,stretchFor,subjectMethod} from './subject-reflection-ui.js?v=0.17.0';
import {discoveryPage,programChoices,careerPossibilities,connectionNote,coveragePanel} from './discovery-ui.js?v=0.17.0&layout=2';
import {makeSampleDraft,draftForMode,persistForMode,journeyBanner,journeyOverview,journeyInterests} from './sample-journey.js?v=0.17.0';
import {earningSummary,earningsIntro,earningsPage,earningsMethod} from './earnings-ui.js';
import {lifestyleChoices,setLifestyleChoice,setHomeMode,updateBudget,confirmLifestyle,nextLifestyleQuestion,lifestyleSnapshot} from './lifestyle-state.js';
import {lifestylePage,lifestyleSummaryPage,lifestyleLens,budgetPreview,money} from './lifestyle-ui.js';
import{STORAGE_KEY,LEGACY_STORAGE_KEY,OLDER_STORAGE_KEY,EARLIEST_STORAGE_KEY,freshDraft,cleanDraft,scorePathways,toggleSaved,careerExamples,stageFor,themeNames}from'./engine.js?v=0.17.0';
import{onetQuestions,onetResponseOptions,onetInstrument,scoreOnetInterest}from'./onet-assessment.js';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const main=document.querySelector('#main');
const isSampleJourney=new URLSearchParams(location.search).get('journey')==='sample';
const browserStore={getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)};
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});
let recordingIdentity=crypto.randomUUID();
let data,occupations,sources,earnings,coverage,s,draftSession,storageAvailable=true,areaFilter='all',query='',tab=new URLSearchParams((location.hash.split('?')[1]||'')).get('view')==='earnings'?'earnings':'overview',programFilter='',careerStage='all',careerLimit=4,programLimit=12,programSearch='',programGroup='all',browseAll=false;
const samples={builder:{name:'Curious builder',raw:[36,33,16,12,18,24]},helper:{name:'People & discovery',raw:[17,32,18,38,20,20]},creator:{name:'Creative communicator',raw:[12,19,38,27,31,15]}};
const link=(text,route,secondary=false)=>`<a class="button${secondary?' secondary':''}" href="#/${route}">${text}</a>`;
const area=id=>data.areas.find(a=>a.id===id);
const path=id=>data.pathways.find(p=>p.id===id);
const saved=id=>s.saved.includes(id);
function announce(message){if(!isSampleJourney&&draftSession&&['conflict','error','unsupported','quota','busy','migration'].includes(draftSession.status))message='Changes in this tab are not saved. Review the draft notice above.';document.querySelector('#notice').textContent=message;clearTimeout(announce.timeout);announce.timeout=setTimeout(()=>{document.querySelector('#notice').textContent='';},4500);}
function draftStatus(){
 const box=document.querySelector('#draft-sync-status');if(!box||isSampleJourney)return;
 const rawState=draftSession?.status||'error',state=draftSession?.legacyChanged&&['ready','saved'].includes(rawState)?'legacy-changed':rawState;box.dataset.state=state;
 box.hidden=['ready','saved'].includes(state);
 const messages={migration:'This tab began with an earlier saved draft. Choose Save in updated version to protect the current copy. Earlier tabs keep their separate draft; their later edits will not be merged automatically.',quota:'Browser storage is full. Your latest edits remain in this tab. Export them to keep a copy, then free space and retry saving.',busy:'Another tab is holding up saving. Your edits remain in this tab. Retry saving when that tab is available, or export a copy.', 'legacy-changed':'An older tab changed its separate draft. Your updated-version draft is protected. Export any changes you need from the older tab before refreshing it.',saving:'Saving this draft…',conflict:'Another tab changed the saved draft. This tab may show older answers and clues. Saving is paused to protect the newer draft. Your edits are still in this tab; export them before loading the latest draft.',error:'Browser saving is unavailable, or the saved draft could not be read. Your edits remain in this tab. Export them to keep a copy.',unsupported:'Safe saving across tabs is unavailable in this browser. Your existing saved draft is unchanged. You can explore and export your edits.'};
 box.querySelector('[data-draft-message]').textContent=messages[state]||'';
 box.querySelector('[data-load-latest]').hidden=state==='saving';
 box.querySelector('[data-export]').hidden=state==='saving';
 box.querySelector('[data-adopt-draft]').hidden=state!=='migration';
 box.querySelector('[data-retry-draft]').hidden=!['quota','busy','error'].includes(state);
 box.querySelector('[data-load-latest]').hidden=['saving','legacy-changed','migration'].includes(state);
 storageAvailable=['ready','saved','saving','legacy-changed'].includes(state);
}
function persist(){
 const pending=isSampleJourney?Promise.resolve({status:'sample'}):draftSession.save(s).then(r=>{draftStatus();return r;});draftStatus();
 document.querySelector('#saved-count').textContent=s.saved.length;return pending;
}
window.addEventListener('storage',e=>{if(!isSampleJourney&&draftSession&&(e.key===STORAGE_KEY||e.key===LEGACY_STORAGE_KEY||e.key===OLDER_STORAGE_KEY||e.key===EARLIEST_STORAGE_KEY||e.key===null)){draftSession.checkForUpdates();draftStatus();}});
function resumeDraft(){if(!isSampleJourney&&draftSession){draftSession.checkForUpdates();draftStatus();}}
window.addEventListener('focus',resumeDraft);
window.addEventListener('pageshow',resumeDraft);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')resumeDraft();});
window.addEventListener('beforeunload',e=>{if(!isSampleJourney&&draftSession?.hasUnsaved(s)){e.preventDefault();e.returnValue='';}});
document.querySelector('#draft-sync-status').addEventListener('click',async e=>{
 if(!draftSession)return;
 if(e.target.closest('[data-retry-draft]')){await draftSession.save(s);draftStatus();return;}
 if(e.target.closest('[data-adopt-draft]')){if(!s.activityId)s.activityId=recordingIdentity;const result=await draftSession.adoptLegacy(s);draftStatus();if(result.status==='saved')render();return;}
 const prompt=document.querySelector('[data-draft-replace-prompt]');
 if(e.target.closest('[data-keep-local]')){prompt.hidden=true;return;}
 const replacing=!!e.target.closest('[data-replace-local]');
 if(!replacing&&!e.target.closest('[data-load-latest]'))return;
 if(!replacing&&draftSession.hasUnsaved(s)){prompt.hidden=false;prompt.querySelector('[data-keep-local]').focus();return;}
 prompt.hidden=true;
 const result=await draftSession.loadLatest();if(result.draft){s=result.draft;if(!s.activityId&&!draftSession.needsAdoption){s.activityId=crypto.randomUUID();persist();}render({focus:true});announce('Loaded the latest saved Approach 2 draft. Review its answers before continuing.');}draftStatus();
});
const activity=createActivityRecorder({storage:browserStore,locks:navigator.locks,onStatus:state=>{
 const box=document.querySelector('#activity-status');if(!box)return;
 const labels={ready:'Choice recording starts when you explore.',recorded:'Choice activity recorded.',sending:'Recording choice activity…',pending:'Choice recording pending.',blocked:'Choice recording needs attention.'};
 box.querySelector('[data-activity-message]').textContent=labels[state.status]+(state.error?' '+state.error:'');box.querySelector('[data-retry-activity]').hidden=!['pending','blocked'].includes(state.status);
}});
let activitySequence=Promise.resolve(),lastOpenedPath=null,baselineScope=null;
const activitySource=()=>new URLSearchParams(location.search).get('recording')==='qa'?'qa':isSampleJourney||s.sample?'sample':'actual';
const reportActivityError=()=>{const box=document.querySelector('[data-activity-message]');if(box)box.textContent='Choice recording is waiting; the saved draft is separate. Retry recording.';};
function activityTask(fn){activitySequence=activitySequence.then(fn).catch(reportActivityError);return activitySequence;}
function activityScope(draft=s,source=activitySource()){return recordingJourney(draft.activityId||recordingIdentity,source).then(id=>({id,source}));}
function recordableDraft(draft){return {...draft,choices:{programs:draft.choices.programs.filter(x=>path(x.pathId)?.programs.some(p=>p.cip===x.code)),careers:draft.choices.careers.filter(x=>path(x.pathId)?.occupations.includes(x.code))}};}
function ensureActivityBaseline(){const draft=structuredClone(s),source=activitySource();return activityTask(async()=>{const scope=await activityScope(draft,source),key=scope.id+'|'+source;if(baselineScope!==key){activity.clearContext();baselineScope=key;}await activity.baseline(scope.id,source,recordableDraft(draft));});}
function recordExploration(pathId){const draft=structuredClone(s),source=activitySource();return activityTask(async()=>{const scope=await activityScope(draft,source);await activity.baseline(scope.id,source,recordableDraft(draft));await activity.action(scope.id,source,'pathway_open',{pathId});});}
function recordLowerExploration(kind,pathId,code){if(!pathId)return;const draft=structuredClone(s),source=activitySource();return activityTask(async()=>{const scope=await activityScope(draft,source);await activity.baseline(scope.id,source,recordableDraft(draft));await activity.action(scope.id,source,kind,{pathId,code});});}
main.addEventListener('toggle',e=>{const el=e.target;if(el.matches?.('details[data-career-open]')&&el.open){const current=path((location.hash.split('?')[0].split('/')[2])||'');if(current?.occupations.includes(el.dataset.careerOpen))recordLowerExploration('career_open',current.id,el.dataset.careerOpen);}},true);
function recordSavedAction(kind,pathId,code,revision,pending,draft=structuredClone(s),source=activitySource()){
 return activityTask(async()=>{const result=await pending;if(!['saved','sample'].includes(result.status))return;const scope=await activityScope(draft,source);await activity.baseline(scope.id,source,recordableDraft(draft));await activity.action(scope.id,source,kind,{pathId,...(code?{code}:{}),revision});});
}
function choiceButton(kind,pathId,code){const selected=s.choices[kind].some(x=>x.pathId===pathId&&x.code===code);const title=kind==='programs'?path(pathId)?.programs.find(x=>x.cip===code)?.title:occupations[code]?.title;return `<button class="save small" aria-label="${selected?'Remove':'Save'} ${h(title||code)} ${selected?'from':'to'} my plan" data-choice-kind="${kind}" data-choice-path="${pathId}" data-choice-code="${code}" aria-pressed="${selected}">${selected?'✓ Saved to my plan':'+ Save to my plan'}</button>`;}
function lowerChoicesPlan(){const rows=[...s.choices.programs.map(x=>({...x,kind:'programs'})),...s.choices.careers.map(x=>({...x,kind:'careers'}))];return `<section class="panel"><h2>Majors and careers I’m curious about</h2><p>Optional possibilities to investigate. Saving an option does not commit you to a major or profession.</p>${rows.length?rows.map(x=>{const p=path(x.pathId),title=x.kind==='programs'?p?.programs.find(p=>p.cip===x.code)?.title:occupations[x.code]?.title;return `<div class="program"><div><strong>${h(title||x.code)}</strong><span>${x.kind==='programs'?'Program category':'Career possibility'} · ${h(p?.title||x.pathId)}</span><a href="#/path/${x.pathId}">Revisit pathway ↗</a></div>${choiceButton(x.kind,x.pathId,x.code)}</div>`;}).join(''):'<p class="subtle">No majors or careers saved yet. Explore a pathway’s program choices or career possibilities to keep an option here.</p>'}</section>`;}
function recordRenderedChoices(parts){
 if(!recordingIdentity||parts[0]==='statistics')return;ensureActivityBaseline();
 const open=parts[0]==='path'&&path(parts[1])?parts[1]:null;
 if(open&&lastOpenedPath!==open)recordExploration(open);lastOpenedPath=open;
 if(parts[0]==='pathways'&&areaFilter==='all'&&!query.trim()&&!browseAll){
  const ranked=orderReflectedPathways(scorePathways(data.pathways,profile()),s.reflection),items=subjectSuggestions(ranked),active=!!ranked[0]?.subjectActive,usable=(profile().complete&&!profile().flat&&!profile().nearFlat)||active;
  const draft=structuredClone(s),source=activitySource(),paths=usable?items.map(p=>p.id):[],mode=active?'subjects':usable?'interests':'none';
  activityTask(async()=>{const scope=await activityScope(draft,source);await activity.suggestions(scope.id,source,mode,paths);});
 }
}
window.addEventListener('online',()=>activity.retry());
document.addEventListener('click',e=>{if(e.target.closest('[data-retry-activity]'))activity.retry();if(e.target.closest('[data-refresh-activity]'))loadActivityStatistics();});
function profile(){if(s.sample){const raw=s.sample.raw;return{raw,complete:true,flat:Math.max(...raw)===Math.min(...raw),nearFlat:Math.max(...raw)-Math.min(...raw)<=2,sample:true};}return scoreOnetInterest({profileJourney:{officialInterest:{instrument:onetInstrument.id,version:onetInstrument.version,answers:s.answers}}});}
function saveButton(id){return`<button class="save" data-save="${id}" aria-pressed="${saved(id)}">${saved(id)?'✓ Shortlisted':'+ Shortlist'}</button>`;}
function profileStrip(){const p=profile();if(!p.complete)return'';return`<aside class="profile-strip"><div><strong>${isSampleJourney?'Jordan’s fictional interest reflection':p.sample?'Sample: '+h(s.sample.name):'Your broad interests'}</strong><p>${p.flat||p.nearFlat?'Your interest answers are broadly similar across themes. The interest profiler alone gives no suggested order.':'Starting points based on broad interests. Keep other pathways open as you learn.'}</p></div><div><a href="#/interests" class="text-link">${p.sample?'Try my own answers':'Review my answers'}</a> <button class="text-link" data-clear-profile>Clear ${p.sample?'sample':'answers'}</button></div></aside>`;}
function reflected(p){return orderReflectedPathways(scorePathways(data.pathways,profile()),s.reflection).find(x=>x.id===p.id)||p;}
function card(p){p=reflected(p);const a=area(p.area);return`<article class="path-card ${a.color}"><span class="eyebrow">${h(a.title)}</span><h3><a href="#/path/${p.id}" style="text-decoration:none">${h(p.title)}</a></h3><p>${h(p.summary)}</p><div class="course-tags">${p.courses.slice(0,3).map(c=>`<span>${h(c)}</span>`).join('')}</div>${p.score!==null&&p.score!==undefined?`<p class="reason">Interests to explore here: ${p.reasons.map(h).join(' · ')}</p>`:''}${pathwayReason(p)}${studyIntentBadge(s.studyIntent,p.id)}<small class="subtle">${h(p.route)}</small>${earningSummary(p,earnings,s.lifestyle,{compact:true})}<div class="card-bottom"><a href="#/path/${p.id}">Explore this pathway <span aria-hidden="true">↗</span></a>${saveButton(p.id)}</div></article>`;}
function home(){return`<div class="wrap"><section class="hero"><div><span class="eyebrow"><span class="dot"></span>A college direction, with room to grow</span><h1>You don’t need<br>the job title.<br><em>Start with a direction.</em></h1><p class="lede">Explore what you could study, the skills you could build, and the possibilities a college pathway could open.</p><div class="actions">${link('Start with my lifestyle <span aria-hidden="true">↗</span>','lifestyle')}${link('Explore college pathways','pathways',true)}</div><p class="subtle">Or <a href="#/interests">explore my interests</a>. No career decision required.</p></div><div class="hero-art" aria-label="Your interests lead to college pathways, with several career possibilities underneath"><div class="art-heading">One starting point. Many possibilities.</div><div class="art-node"><small>WHAT DRAWS YOU IN</small><strong>Ideas · People · Making things</strong></div><div class="art-stem"></div><div class="art-node" style="background:#285447;color:white"><small>WHAT YOU COULD STUDY</small><strong>A college pathway</strong></div><div class="art-row"><div class="art-node"><small>ONE POSSIBILITY</small><strong>Work you discover</strong></div><div class="art-node"><small>ANOTHER POSSIBILITY</small><strong>A new direction</strong></div></div><div class="art-note">Different futures can share a beginning.</div><span class="scribble">keep a few doors open ↗</span></div></section><div class="principles"><div><strong>Start with what you’d learn</strong><span>Subjects and courses before job titles.</span></div><div><strong>Keep related options together</strong><span>See where shared preparation could lead.</span></div><div><strong>Take one useful next step</strong><span>Compare a course. Try a project. Ask a question.</span></div></div><section><div class="section-heading"><div><span class="eyebrow">A little curiosity goes a long way</span><h2>Which world draws you in?</h2><p>Start anywhere. You can explore more than one.</p></div><a class="text-link" href="#/pathways">See all ${data.pathways.length} pathways ↗</a></div><div class="area-grid">${data.areas.map((a,i)=>`<a class="area-card ${a.color}" href="#/pathways?area=${a.id}"><span class="area-icon" aria-hidden="true">${['⌘','∿','+','✳','✎','↗'][i]}</span><h3>${h(a.title)}</h3><p>${h(a.description)}</p><small>${data.pathways.filter(p=>p.area===a.id).length} pathways to explore</small><span class="arrow" aria-hidden="true">↗</span></a>`).join('')}</div></section><aside class="callout"><div><h3>Want to see a complete student journey?</h3><p>Follow a fictional student from lifestyle choices and all 60 interest responses to comparing college pathways, earnings and next steps.</p><p style="margin:16px 0"><a class="text-link" href="./?v=0.17.0&journey=sample#/journey">Walk through Jordan’s sample journey ↗</a></p><p>Or preview a broad interest pattern:</p><div class="sample-options">${Object.entries(samples).map(([id,p])=>`<button data-sample="${id}">${h(p.name)} ↗</button>`).join('')}</div></div></aside></div>`;}
function pathwaysPage(){return discoveryPage({data,occupations,sources,profile:profile(),areaFilter,query,browseAll,card,lifestyle:lifestyleLens(s.lifestyle,{compact:true}),profileStrip:profileStrip(),earningsIntro:earningsIntro(earnings),reflection:s.reflection,subjectStrip:subjectStrip(s.reflection,orderReflectedPathways(scorePathways(data.pathways,profile()),s.reflection))});}
function examples(p,limit=3){return careerExamples(p,occupations,programFilter).slice(0,limit);}
function occupationCard(o){const currentPath=path((location.hash.split('?')[0].split('/')[2])||'');return`<article class="career"><h3>${h(o.title)}</h3><p>${h(o.summary)}</p><p class="stage">${h(stageFor(o))}</p><p class="subtle">${h(connectionNote(o))}</p><details data-career-open="${o.soc}"><summary>Look inside this career</summary>${o.tasks?.length?'<p><strong>A few things people do</strong></p><ul>'+o.tasks.slice(0,3).map(t=>'<li>'+h(t.text)+'</li>').join('')+'</ul>':'<p>Detailed task information is unavailable in this source record.</p>'}${[['skills','Skills used'],['knowledge','Knowledge areas'],['abilities','Abilities used'],['workStyles','Work styles'],['specificInterests','Occupation interest areas']].map(([key,label])=>o[key]?.length?'<p><strong>'+label+':</strong> '+o[key].map(x=>h(x.name)).join(' · ')+'</p>':'').join('')}${o.preparation?'<p><strong>Typical preparation:</strong> '+h(o.preparation.education)+'; '+h(o.preparation.experience)+' related experience; '+h(o.preparation.training)+' on-the-job training. Base-SOC classification; specialist requirements can differ.</p>':''}<p>These describe the occupation. They do not assess your current ability or establish that a particular degree qualifies you.</p></details><div class="actions"><a href="${h(o.url)}" target="_blank" rel="noopener">Full O*NET profile ↗</a>${currentPath?.occupations.includes(o.soc)?choiceButton('careers',currentPath.id,o.soc):''}</div></article>`;}
function pathPage(p){if(!p)return notFound();p=reflected(p);const a=area(p.area),rows=careerExamples(p,occupations,programFilter);return`<div class="wrap"><a class="back" href="#/pathways">← All pathways</a><section class="detail-head"><div><span class="eyebrow">${h(a.title)}</span><h1>${h(p.title)}</h1><p class="lede">${h(p.summary)}</p><div class="actions">${saveButton(p.id)}${link('Compare my shortlist','shortlist',true)}</div></div><aside class="detail-aside ${a.color}"><span class="eyebrow">Your starting point</span><p><strong>${h(p.route)}</strong></p><p style="margin-top:12px">Start by comparing the programs and what you would learn. You can decide on a specialty later.</p></aside></section>${lifestyleLens(s.lifestyle,{compact:true})}${tab==='overview'?studyIntentQuestions(p,s.studyIntent):''}<div class="tabs" role="tablist" aria-label="Pathway details">${[['overview','The big picture'],['study','Majors & degree routes'],['careers','Career possibilities'],['earnings','Earnings & my lifestyle']].map(([id,label])=>`<button id="tab-${id}" class="tab ${tab===id?'active':''}" role="tab" aria-selected="${tab===id}" aria-controls="tab-content" data-tab="${id}">${label}</button>`).join('')}</div><section id="tab-content" role="tabpanel" aria-labelledby="tab-${tab}">${tab==='overview'?`<div class="detail-grid"><div><section class="panel"><span class="eyebrow">What you might study</span><h2>Build a foundation.<br>Find your own emphasis.</h2><ul class="course-list">${p.courses.map((c,i)=>`<li><span>0${i+1}</span>${h(c)}</li>`).join('')}</ul><p class="subtle">Illustrative subject areas. Actual degree plans vary by college and major.</p></section><section class="panel"><h3>Why explore this direction?</h3>${pathwayReason(p)||'<p>Start with the subjects below and see what you want to try. No specific subject connection is established yet.</p>'}<h3>A stretch to try</h3><p>${h(stretchFor(p))}</p><h3>Try a little of it first</h3><p>${h(p.activity)}</p><p>${h(p.compare)}</p></section></div><div>${routeComparison(p,s.studyIntent.answers[p.id],true)}<button class="text-link" data-tab="study">Search program choices ↗</button><section class="panel"><h3>A few possible destinations</h3><p>${careerExamples(p,occupations).slice(0,3).map(o=>h(o.title)).join(' · ')}</p><p>These are education-linked examples, not promises of eligibility or job outcomes.</p><button class="text-link" data-tab="careers">Explore the possibilities ↗</button></section></div></div>${earningSummary(p,earnings,s.lifestyle)}`:tab==='earnings'?earningsPage(p,earnings,s.lifestyle):tab==='study'?`<div class="detail-grid"><section class="panel"><h2>Related program choices</h2><p>These official program categories share this exploration area. They can be separate majors or credentials. Choose the actual program before checking career eligibility.</p>${programChoices(p,programLimit,{query:programSearch,group:programGroup,programButton:(pathId,code)=>choiceButton('programs',pathId,code)})}</section><aside>${routeComparison(p,s.studyIntent.answers[p.id],true)}<section class="panel"><h3>Before you choose a program</h3><ul><li>Compare first-year courses and admission prerequisites.</li><li>Check the award: certificate, associate, bachelor’s or graduate degree.</li><li>Review accreditation and licensing eligibility where relevant.</li><li>Ask about transfer credit, placements and internships.</li><li>Compare tuition, aid, living costs and time to complete.</li></ul></section><p class="note">${h(p.caution)}</p><p class="subtle">Program categories and occupation connections come from the official O*NET education crosswalk. Group names and study suggestions are Fieldguide’s editorial study groupings.</p></aside></div>`:careerPossibilities(p,occupations,{programFilter,stageFilter:careerStage,limit:careerLimit,occupationCard})}</section><aside class="callout"><div><h3>You can explore this without choosing a job.</h3><p>Keep up to three pathways on your shortlist, then plan a small next step for each.</p></div>${saved(p.id)?link('Make my next-step plan','plan'):`<button class="button" data-save="${p.id}">Add to my shortlist +</button>`}</aside></div>`;}
function shortlistPage(){const ps=s.saved.map(path).filter(Boolean);return`<div class="wrap"><section class="page-intro"><span class="eyebrow">My shortlist</span><h1>A few possibilities<br>to sit with.</h1><p class="lede">Keep up to three pathways side by side. Compare what you’d study and the preparation involved, then choose what to investigate next.</p></section>${lifestyleLens(s.lifestyle,{compact:true})}${ps.length?`<div class="path-grid">${ps.map(card).join('')}</div><div class="actions">${link('Compare these pathways','compare')}${link('Make my next-step plan','plan',true)}${link('Explore another area','pathways',true)}</div>`:`<div class="empty"><h2>Start with one possibility.</h2><p>Explore the pathways and shortlist the ones you want to learn more about.</p>${link('Explore pathways','pathways')}</div>`}</div>`;}
function comparePage(){const ps=s.saved.map(path).filter(Boolean).map(reflected);return`<div class="wrap"><a class="back" href="#/shortlist">← My shortlist</a><section class="page-intro"><span class="eyebrow">See them side by side</span><h1>Compare beginnings,<br>not a final destination.</h1><p class="lede">Look for subjects you want to spend time with and routes you’re willing to explore.</p></section>${lifestyleLens(s.lifestyle,{compact:true})}${ps.length?`${routeComparison({title:'your shortlist',route:'Use each pathway’s education context below; compare named programs separately.',caution:'A similar subject can lead through different awards. Compare prerequisites, transfer and later professional requirements.'})}<div class="compare-grid ${ps.length<3?'cols-2':''}">${ps.map(p=>`<article class="compare-cell"><h2>${h(p.title)}</h2>${studyIntentBadge(s.studyIntent,p.id)}${pathwayReason(p)||'<p class="subtle">No specific subject connection yet. You can still explore this pathway.</p>'}<h3>First-year subjects to investigate</h3><ul>${p.courses.slice(0,3).map(c=>'<li>'+h(c)+'</li>').join('')}</ul><p class="subtle">Illustrative subjects; check actual first-year course lists.</p>${earningSummary(p,earnings,s.lifestyle)}<h3>Education route</h3><p>${h(p.route)}</p><p class="subtle">Your first route comparison: ${h(preparationLabel(s.studyIntent.answers[p.id]?.route))}</p><h3>A stretch to try</h3><p>${h(stretchFor(p))}</p><h3>What needs a closer look</h3><p>${h(p.caution)}</p><h3>A small experiment</h3><p>${h(p.activity)}</p><h3>Time & prerequisites to check</h3><p>Ask the college for the full sequence, including prerequisites, accepted transfer credits, placements and any later qualifying study. Duration depends on the actual program and your starting point.</p><h3>Lifestyle & cost questions</h3><p>Compare named programs, net price after grants, transfer options and total time in education. Program-specific prices are not assessed in this prototype.</p><a class="text-link" href="#/path/${p.id}">Explore this pathway ↗</a></article>`).join('')}</div>${earningsMethod(earnings)}<div class="actions">${link('Make my next-step plan','plan')}${link('Review my shortlist','shortlist',true)}</div>`:`<div class="empty"><p>Shortlist a pathway first. Add a second when you want to compare.</p>${link('Explore pathways','pathways')}</div>`}</div>`;}
function taskTexts(p){return[['Try a small piece of the subject',p.activity],['Compare two real programs',p.compare],['Ask about preparation, costs & graduate outcomes','Ask which named programs keep several qualifying routes open. Compare net price, completion time, placements and published graduate earnings with the pathway’s occupational wage examples.']];}
function planPage(){const ps=s.saved.map(path).filter(Boolean);return`<div class="wrap"><section class="page-intro"><span class="eyebrow">My next steps</span><h1>A plan to learn more.<br>Not a promise for life.</h1><p class="lede">Your plan starts with the pathways you’re curious about. Try something, notice what you learn, and come back with new questions.</p></section>${lifestyleLens(s.lifestyle,{compact:true})}${studyIntentPlan(data.pathways,s.studyIntent)}${lowerChoicesPlan()}${(ps.length||s.choices.programs.length||s.choices.careers.length||Object.keys(s.studyIntent.answers).length)?`<div class="actions"><button class="button" data-print>Print / save PDF ↗</button><button class="button secondary" data-export>Export full draft (lifestyle & subjects)</button></div>${!ps.length?'<p class="note">Your saved possibilities are above. Add a college pathway when you want to compare broad directions.</p>':''}${ps.map(p=>`<section class="panel"><div class="section-heading" style="margin:0 0 20px"><div><span class="eyebrow">${h(area(p.area).title)}</span><h2>${h(p.title)}</h2></div><a class="text-link" href="#/path/${p.id}">Revisit pathway ↗</a></div>${studyIntentBadge(s.studyIntent,p.id)}${earningSummary(p,earnings,s.lifestyle,{compact:true})}${taskTexts(p).map(([title,copy],i)=>`<label class="plan-item"><input type="checkbox" data-task="${p.id}:${i}" ${s.tasks[p.id+':'+i]?'checked':''}><span><strong>${h(title)}</strong><small>${h(copy)}</small></span></label>`).join('')}<label class="field-label" for="notes-${p.id}" style="margin-top:25px">What I’m curious about, and what I learned</label><textarea id="notes-${p.id}" maxlength="4000" data-note="${p.id}" placeholder="Questions, programs to compare, something you tried…">${h(s.notes[p.id]||'')}</textarea><p class="subtle">${storageAvailable?'Saved in this browser for Approach 2 only.':'Browser saving is unavailable. Export your draft to keep a copy.'}</p></section>`).join('')}<p class="note">You haven’t committed to a major or profession. Change your shortlist as you discover more.</p>`:`<div class="empty"><h2>Your first step is curiosity.</h2><p>Shortlist a college pathway to create a plan. You don’t need to choose a career.</p>${link('Find a pathway to explore','pathways')}</div>`}</div>`;}
function interestsPage(index){const answered=Object.keys(s.answers).length;return`<div class="wrap"><div class="question-layout">${index===null?`<span class="eyebrow">An optional starting point</span><h1>What would you<br>enjoy exploring?</h1><p class="lede">The 60-item O*NET® Interest Profiler asks about activities you might enjoy. Think about your interest, even if you haven’t learned how to do the activity yet.</p><p>You can pause and browse pathways at any time. Your answers stay in this prototype’s browser draft.</p><div class="actions">${link(answered?'Resume my answers ('+answered+'/60)':'Begin interest questions','interests/'+Math.min(onetQuestions.findIndex(q=>!s.answers[q.id])<0?0:onetQuestions.findIndex(q=>!s.answers[q.id]),59))}${link('Browse pathways instead','pathways',true)}</div><p>Prefer thinking about classes and projects? <a href="#/subjects">Try the separate optional subject reflection ↗</a></p><div class="panel"><h3>Just previewing?</h3><p>Try a fictional sample. It is labeled throughout and stays separate from your own answers.</p><div class="sample-options">${Object.entries(samples).map(([id,p])=>`<button data-sample="${id}">${h(p.name)} ↗</button>`).join('')}</div></div><details><summary>About this interest reflection</summary><p>${h(onetInstrument.attribution)}</p><p>Original item text and response labels are preserved. Fieldguide’s pathway grouping and ranking are separate editorial methods, not official O*NET program recommendations or an aptitude assessment.</p><a href="${onetInstrument.scoringURL}" target="_blank" rel="noopener">O*NET Interest Profiler manual ↗</a></details>`:questionPage(index)}</div></div>`;}
function questionPage(i){const q=onetQuestions[i];if(!q)return'<p>Question unavailable.</p>';return`<span class="eyebrow">O*NET® Interest Profiler · ${i+1} of 60</span><div class="progress-track" role="progressbar" aria-label="Interest questions answered" aria-valuenow="${Object.keys(s.answers).length}" aria-valuemin="0" aria-valuemax="60"><div style="width:${Object.keys(s.answers).length/60*100}%"></div></div><h1>${h(q.text)}</h1><p class="subtle">How would you feel about doing this activity?</p><div class="responses">${onetResponseOptions.map(o=>`<button data-answer="${o.value}" data-question-index="${i}" aria-pressed="${s.answers[q.id]===o.value}">${h(o.label)}<span aria-hidden="true">${s.answers[q.id]===o.value?'✓':'→'}</span></button>`).join('')}</div><div class="question-foot">${i?`<a href="#/interests/${i-1}">← Previous</a>`:'<a href="#/interests">← Introduction</a>'}<a href="#/pathways">Pause & explore pathways</a></div><small class="subtle">${h(onetInstrument.attribution)}</small>`;}
function aboutPage(){return`<div class="wrap"><section class="page-intro"><span class="eyebrow">Approach 2 · an independent prototype</span><h1>Full possibilities.<br>A simpler starting point.</h1><p class="lede">Fieldguide — Approach 2: College Pathways explores a college direction before narrowing to a profession.</p></section><div class="stat-row"><div><strong>${sources.occupations.toLocaleString()}</strong><span>occupation records retained</span></div><div><strong>${sources.withInterestVectors}</strong><span>with O*NET interest data</span></div><div><strong>${data.pathways.length}</strong><span>broad study pathways</span></div></div><div class="detail-grid"><div><section class="panel"><h2>Two approaches. Separate projects.</h2><p><strong>Approach 1: Career Explorer</strong> is the existing Fieldguide application. Its files, build, hosted site and student storage are unchanged.</p><p><strong>Approach 2: College Pathways</strong> has its own source folder, copied source data, deployment and browser draft. It can operate without Approach 1 running.</p><p>Answers, subject reflections, study intentions, lifestyle budgets and notes entered here stay in your browser. Pathways shown and opened, shortlist changes, and programs or careers saved to your plan are recorded in this private Approach 2 Site for choice statistics. No assessment answers, budget amounts or notes are sent with these events. Existing saved options are labeled as imported; samples and QA runs remain separate. This prototype does not connect to the existing Firebase student accounts.</p></section><section class="panel"><h3>What the groupings mean</h3><p>Program-to-occupation connections come from the official O*NET CIP crosswalk (2020 CIP, O*NET-SOC 2019, July 2024 update). Program codes are grouped into ${data.pathways.length} editorial study pathways across six broad areas. Certificates, associate and bachelor’s routes, graduate programs and later training are distinguished within them.</p><p>A pathway may contain several distinct majors or credentials. Programs and occupations can appear in more than one pathway. Shared interests or shared grouping do not make degrees interchangeable.</p><p>All ${sources.occupations.toLocaleString()} occupations are retained. All ${sources.collegeRelevant} occupations meeting the disclosed college-exploration policy are grouped into pathways: ${sources.officialProgramLinked} with official program links and ${sources.editorialOnly} with separately labeled BLS-based editorial connections. Other titles remain in source lookup; absence from a pathway does not mean college is inaccessible or unhelpful.</p></section><section class="panel"><h3>How starting points are suggested</h3><p>Your six O*NET Interest Profiler raw scores are compared with a disclosed editorial study-theme profile for each pathway. A normalized weighted mean orders pathways; the number of occupations in a pathway has no effect on that order.</p><p>Pathway weights use a 1–5 editorial emphasis scale; the calculation uses weight minus one and divides by the sum of those effective weights. Scores are never shown as fit percentages. Flat or nearly flat profiles produce no suggested order. Incomplete answers do not create a score.</p><p>Career examples are education-linked illustrations, not individually assessed matches. Extra preparation and experience need their own review. This prototype has not been validated as a predictor of student outcomes.</p><p>The two original study-intention questions are optional planning reflections. Choosing a hobby, a route to compare or Unsure labels your plan; it does not change matching scores or subject clues. Saved possibilities stay as chosen until you change them.</p><details><summary>Inspect the pathway weights</summary><p>Theme order: ${themeNames.map(h).join('; ')}.</p><ul>${data.pathways.map(p=>`<li>${h(p.title)}: ${p.weights.join(', ')}</li>`).join('')}</ul></details></section>${subjectMethod(data.pathways)}</div><aside><section class="panel"><h3>Sources & attribution</h3><p>O*NET® 31.0 Database, U.S. Department of Labor, Employment and Training Administration. Source snapshot: ${sources.sourceSnapshotDate}. Independent prototype: ${sources.prototypeDate}.</p><ul><li><a href="${sources.database}" target="_blank" rel="noopener">Official O*NET database</a></li><li><a href="${sources.crosswalk}" target="_blank" rel="noopener">Official education crosswalk (XLSX)</a></li><li><a href="${sources.license}" target="_blank" rel="noopener">Database: CC BY 4.0</a></li><li><a href="${onetInstrument.licenseURL}" target="_blank" rel="noopener">Interest Profiler: CC BY-ND 4.0</a></li></ul><p>Occupation examples show selected tasks and descriptors. Full imported tables are retained in the prototype’s local source cache. External occupation links provide fuller official detail.</p><p>The lifestyle questionnaire and editable budget use Approach 1’s dated 2026 model through a pinned shared release. Lifestyle does not change pathway ranking. Selected local earning examples can be compared with your confirmed budget, with further-study and experienced destinations shown separately. College-specific tuition, financial aid and verified licensing routes are not implemented.</p></section><section class="panel"><h3>My prototype data</h3><p>Clear only this experiment’s browser draft, or export it before starting again.</p><div class="actions"><button class="button secondary small" data-export>Export full draft (lifestyle & subjects)</button><button class="text-link" data-reset>Clear Approach 2 draft</button></div><p class="subtle">Approach 1’s browser data and account saves are separate.</p></section></aside></div>${earningsMethod(earnings)}${coveragePanel(coverage)}<section class="panel"><h2>Look up any occupation</h2><p>Optional source lookup. The main student journey stays focused on college pathways.</p><label class="field-label" for="occupation-search">Search the complete occupation inventory</label><input id="occupation-search" class="library-search" type="search" placeholder="Occupation title or O*NET code"><div id="occupation-results" class="career-list"></div></section></div>`;}
function notFound(){return`<div class="wrap"><h1>Let’s find your next direction.</h1>${link('Explore college pathways','pathways')}</div>`;}
function render({focus=false}={}){let raw=location.hash.slice(1)||'/',[route,q='']=raw.split('?'),parts=route.split('/').filter(Boolean);if(parts[0]==='pathways'&&new URLSearchParams(q).has('area')){const candidate=new URLSearchParams(q).get('area');areaFilter=data.areas.some(a=>a.id===candidate)?candidate:'all';}let html;if(!parts.length)html=home();else if(parts[0]==='journey'&&isSampleJourney)html=parts[1]==='interests'?journeyInterests(s):journeyOverview(s,data,earnings);else if(parts[0]==='pathways')html=pathwaysPage();else if(parts[0]==='path')html=pathPage(path(parts[1]));else if(parts[0]==='shortlist')html=shortlistPage();else if(parts[0]==='compare')html=comparePage();else if(parts[0]==='plan')html=planPage();else if(parts[0]==='lifestyle')html=parts[1]==='summary'?lifestyleSummaryPage(s.lifestyle):lifestylePage(s.lifestyle,parts.length>1?Number(parts[1]):null);else if(parts[0]==='subjects')html=subjectPage(s.reflection,parts[1],scorePathways(data.pathways,profile()),{sample:isSampleJourney});else if(parts[0]==='interests')html=interestsPage(parts.length>1?Number(parts[1]):null);else if(parts[0]==='about')html=aboutPage();else if(parts[0]==='statistics')html=activityStatisticsPage();else html=notFound();if(isSampleJourney)html=html.replaceAll('Saved in this browser for Approach 2 only.','Sample edits last in this tab only.').replaceAll('Your confirmed goal is saved in this browser for Approach 2.','Jordan’s fictional goal is confirmed for this tab.').replaceAll('Your draft is saved. Confirm it to use the goal alongside your pathways.','Sample edits last in this tab. Confirm the goal to compare pathways.').replaceAll('Clear Approach 2 draft','Restart fictional sample').replaceAll('Your answers stay in this prototype’s browser draft.','These fictional responses are held in this sample tab.').replaceAll('Your answers save separately in Approach 2 on this browser.','In this fictional sample, answers last only in this tab.').replaceAll('Answers save only in this prototype’s browser storage.','This fictional sample does not read or write your saved browser draft.').replaceAll('Your latest choices are saved.','Your latest fictional choices are held in this tab.');main.innerHTML=(isSampleJourney?journeyBanner(parts.join('/')):'')+(activitySource()==='qa'?'<p class="wrap note">QA recording mode · these actions stay outside real-journey statistics.</p>':'')+html;recordRenderedChoices(parts);if(parts[0]==='statistics')loadActivityStatistics();if(parts[0]==='about'&&new URLSearchParams(q).get('section')==='earnings'){const method=document.querySelector('#earnings-method');if(method){method.open=true;requestAnimationFrame(()=>method.scrollIntoView());}}if(parts[0]==='about'&&new URLSearchParams(q).get('section')==='coverage'){const method=document.querySelector('#coverage-method');if(method){method.open=true;requestAnimationFrame(()=>method.scrollIntoView());}}document.querySelector('#saved-count').textContent=s.saved.length;if(focus)main.focus({preventScroll:true});document.title=(isSampleJourney?'Fictional sample · Jordan · ':'')+(parts[0]==='path'&&path(parts[1])?path(parts[1]).title+' · ':'')+'Fieldguide — Approach 2: College Pathways';}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||!s)return;if(el.dataset.choiceKind){const kind=el.dataset.choiceKind,pathId=el.dataset.choicePath,code=el.dataset.choiceCode,p=path(pathId);if(!['programs','careers'].includes(kind)||!p||(kind==='programs'?!p.programs.some(x=>x.cip===code):!p.occupations.includes(code)))return;const list=s.choices[kind],index=list.findIndex(x=>x.pathId===pathId&&x.code===code),adding=index<0;if(adding&&list.length===24){announce('You have saved 24 options in this group. Remove an option to make room.');return;}if(adding)list.push({pathId,code});else list.splice(index,1);s.choiceRevision++;const pending=persist();recordSavedAction((kind==='programs'?'program':'career')+(adding?'_save':'_remove'),pathId,code,s.choiceRevision,pending);render();announce(adding?'Saved this possibility to your next-step plan.':'Removed this possibility from your plan.');}else if(el.dataset.save){const ok=toggleSaved(s,el.dataset.save,data.pathways.map(p=>p.id));if(!ok){announce('Your shortlist has three pathways. Remove one to make room for another.');return;}s.choiceRevision++;const pending=persist();recordSavedAction(saved(el.dataset.save)?'shortlist_add':'shortlist_remove',el.dataset.save,'',s.choiceRevision,pending);render();announce(saved(el.dataset.save)?'Added to your Approach 2 shortlist.':'Removed from your shortlist.');}else if(el.dataset.area){areaFilter=el.dataset.area;query='';browseAll=false;if(location.hash.includes('?'))history.replaceState(null,'','#/pathways');render();}else if('browseAll'in el.dataset){browseAll=true;render();}else if('morePrograms'in el.dataset){const later=!!el.closest('.later-programs');programLimit+=20;render();if(later)document.querySelector('.later-programs').open=true;}else if('moreCareers'in el.dataset){careerLimit+=20;render();}else if('fewerCareers'in el.dataset){careerLimit=4;render();}else if(el.dataset.tab){tab=el.dataset.tab;render();document.querySelector('#tab-'+tab)?.focus({preventScroll:true});}else if(el.dataset.programLink){recordLowerExploration('program_open',path((location.hash.split('?')[0].split('/')[2])||'')?.id,el.dataset.programLink);programFilter=el.dataset.programLink;careerLimit=4;tab='careers';render();document.querySelector('#tab-careers')?.focus();}else if(el.dataset.sample){s.sample=structuredClone(samples[el.dataset.sample]);persist();if(location.hash==='#/pathways')render();else location.hash='/pathways';}else if('clearProfile'in el.dataset){if(s.sample)s.sample=null;else s.answers={};persist();render();}else if(el.dataset.answer){const i=Number(el.dataset.questionIndex),v=Number(el.dataset.answer);if(!onetQuestions[i]||!Number.isInteger(v)||v<1||v>5)return;s.sample=null;s.answers[onetQuestions[i].id]=v;persist();location.hash=i===59?'/subjects':'/interests/'+(i+1);}else if('print'in el.dataset){window.print();}else if('export'in el.dataset){const blob=new Blob([JSON.stringify({prototype:'Fieldguide — Approach 2: College Pathways',...(isSampleJourney?{fictionalSample:true,sampleStudent:'Jordan'}:{}),...s},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=isSampleJourney?'fieldguide-jordan-fictional-sample.json':'fieldguide-approach-2-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else if('reset'in el.dataset){if(isSampleJourney){s=makeSampleDraft();persist();render();announce('Jordan’s fictional sample restarted. Your own draft is untouched.');return;}if(window.confirm('Clear only your Approach 2 answers, lifestyle budget, shortlist, saved program and career possibilities, and notes in this browser? Historical choice counts are retained in the private statistics.')){const previous=structuredClone(s),source=activitySource();previous.choiceRevision++;s=freshDraft();s.activityId=crypto.randomUUID();recordingIdentity=s.activityId;const pending=persist();activityTask(async()=>{const result=await pending;if(result.status==='saved'){const scope=await activityScope(previous,source);await activity.action(scope.id,source,'journey_clear',{revision:previous.choiceRevision});}});activity.clearContext();render();announce('Approach 2 draft cleared.');}}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='program-search'){const start=el.selectionStart;programSearch=el.value;programLimit=12;render();const next=document.querySelector('#program-search');next?.focus({preventScroll:true});next?.setSelectionRange(start,start);}else if(el.id==='path-search'){const start=el.selectionStart;query=el.value;render();const next=document.querySelector('#path-search');next?.focus();next?.setSelectionRange(start,start);}else if(el.dataset.note){s.notes[el.dataset.note]=el.value.slice(0,4000);persist();}else if(el.id==='occupation-search'){const q=el.value.trim().toLowerCase(),rows=q?Object.values(occupations).filter(o=>(o.title+' '+o.soc).toLowerCase().includes(q)):[];document.querySelector('#occupation-results').innerHTML=q?rows.slice(0,12).map(occupationCard).join('')+`<p class="subtle">${rows.length} results${rows.length>12?' · showing the first 12':''}</p>`:'';}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.intentField){if(setStudyIntent(s.studyIntent,el.dataset.intentPath,el.dataset.intentField,el.value,data.pathways.map(p=>p.id))){persist();render();document.querySelector('#'+el.id)?.focus({preventScroll:true});}return;}if(el.id==='program-group'){programGroup=el.value;programLimit=12;render();document.querySelector('#program-group')?.focus({preventScroll:true});return;}if(el.id==='activity-source'){setActivityStatisticsSource(el.value);return;}if(el.id==='activity-path-filter'){setActivityStatisticsPath(el.value);return;}if(el.id==='program-filter'){programFilter=el.value;careerStage='all';careerLimit=4;render();document.querySelector('#program-filter')?.focus({preventScroll:true});}else if(el.id==='career-stage'){careerStage=el.value;careerLimit=4;render();document.querySelector('#career-stage')?.focus({preventScroll:true});}else if(el.dataset.task){s.tasks[el.dataset.task]=el.checked;persist();}});
window.addEventListener('hashchange',()=>{tab=new URLSearchParams((location.hash.split('?')[1]||'')).get('view')==='earnings'?'earnings':'overview';programFilter='';careerStage='all';careerLimit=4;programLimit=12;programSearch='';programGroup='all';browseAll=false;if(location.hash==='#/pathways'){areaFilter='all';query='';}render({focus:true});window.scrollTo(0,0);});
try{[data,occupations,sources,earnings,coverage]=await Promise.all(['pathways','occupations','sources','pathway-earnings','coverage'].map(async x=>{const r=await fetch('./data/'+x+'.json?v=0.17.0');if(!r.ok)throw Error('Data unavailable: '+x);return r.json();}));if(isSampleJourney){s=makeSampleDraft();}else{draftSession=createDraftSession({storage:browserStore,key:STORAGE_KEY,legacyKey:LEGACY_STORAGE_KEY,legacyFallbackKey:OLDER_STORAGE_KEY,extraLegacyKeys:[EARLIEST_STORAGE_KEY],ids:data.pathways.map(p=>p.id),locks:navigator.locks,onStatus:()=>draftStatus()});s=draftSession.draft;recordingIdentity=s.activityId||await acquireActivityIdentity({storage:browserStore,locks:navigator.locks});}if(!s.activityId&&(isSampleJourney||!draftSession.needsAdoption)){s.activityId=recordingIdentity;if(!isSampleJourney)persist();}render();draftStatus();}catch(error){main.innerHTML=`<div class="error"><h1>We couldn’t open the pathways.</h1><p>Reload this page to try again.</p><p class="subtle">${h(error.message)}</p></div>`;console.error(error);}

document.addEventListener('click',e=>{
 const el=e.target.closest('button');if(!el||!s)return;
 if(el.dataset.lifestyleNext!==undefined){const i=Number(el.dataset.lifestyleNext),q=lifestyleChoices[i];if(!q||!Number.isInteger(s.lifestyle.builder.choices[q.id])){const error=document.querySelector('#lifestyle-error');if(error)error.textContent='Choose a possibility before continuing, or pause to explore pathways.';return;}s.lifestyle.builder.step=Math.min(i+1,8);persist();location.hash=i===8?'/lifestyle/summary':'/lifestyle/'+(i+1);}
 else if('confirmLifestyle'in el.dataset){if(!confirmLifestyle(s.lifestyle)){const error=document.querySelector('#lifestyle-error');if(error)error.textContent='Review the missing choices or invalid budget amounts before using this goal.';return;}persist();render();announce(isSampleJourney?'Jordan’s fictional lifestyle goal is confirmed for this tab.':'Your lifestyle goal is saved alongside your college pathways.');}
});
document.addEventListener('change',e=>{const el=e.target;if(!s)return;if(el.dataset.lifestyleQuestion){if(setLifestyleChoice(s.lifestyle,el.dataset.lifestyleQuestion,Number(el.value))){persist();render();document.querySelector('input[data-lifestyle-question="'+el.dataset.lifestyleQuestion+'"][value="'+el.value+'"]')?.focus({preventScroll:true});}}else if(el.dataset.homeMode){if(setHomeMode(s.lifestyle,el.dataset.homeMode)){persist();render();document.querySelector('input[data-home-mode="'+el.dataset.homeMode+'"]')?.focus({preventScroll:true});}}});
document.addEventListener('input',e=>{const el=e.target;if(!s||!el.dataset.budgetField)return;if(updateBudget(s.lifestyle,el.dataset.budgetField,el.value)){persist();const out=document.querySelector('#budget-preview');if(out)out.innerHTML=budgetPreview(s.lifestyle);const label=document.querySelector('#lifestyle-save-status');if(label)label.textContent=isSampleJourney?'Your fictional edits last in this tab. Confirm the updated goal when ready.':'Your edits are saved as a draft. Confirm the updated lifestyle goal when ready.';const confirm=document.querySelector('[data-confirm-lifestyle]');if(confirm)confirm.textContent='Use updated lifestyle goal ↗';}});

// Original course reflection uses separate state and leaves official profiler answers intact.
main.addEventListener('click',e=>{
 const el=e.target.closest('button');if(!el||!s)return;
 if(el.dataset.subjectQuestion){
  if(!setSubjectAnswer(s.reflection,el.dataset.subjectQuestion,el.dataset.subjectChoice)){announce('Choose up to two options. Deselect one to make room.');return;}
  const q=el.dataset.subjectQuestion,c=el.dataset.subjectChoice;persist();render();
  const target=main.querySelector(`[data-subject-question="${q}"][data-subject-choice="${c}"]`);(target||main).focus({preventScroll:true});
 }else if('subjectMode'in el.dataset){s.reflection.useForSuggestions=el.dataset.subjectMode==='on';persist();render();main.focus({preventScroll:true});
 }else if('subjectClear'in el.dataset){s.reflection=freshReflection();persist();render();main.querySelector('h1')?.scrollIntoView();main.focus({preventScroll:true});announce('Only the subject reflection was cleared. Your interests, lifestyle and shortlist are retained.');
 }else if('subjectSample'in el.dataset&&isSampleJourney){s.reflection=jordanSubjectReflection();persist();location.hash='/subjects/summary';}
});
